1. //! GitHub release client used by `derrick upgrade`.
2. 
3. use reqwest::header::{ACCEPT, USER_AGENT};
4. use serde::{Deserialize, Deserializer};
5. use thiserror::Error;
6. 
7. const RELEASES_URL: &str = "https://api.github.com/repos/lgulliver/derrick/releases?per_page=1";
8. 
9. /// A GitHub release returned by the latest-release endpoint.
10. #[derive(Debug, Deserialize)]
11. pub struct Release {
12.     #[serde(deserialize_with = "deserialize_semver_tag_name")]
13.     tag_name: String,
14.     assets: Vec<ReleaseAsset>,
15. }
16. 
17. impl Release {
18.     /// Returns the release tag name.
19.     #[must_use]
20.     pub fn tag_name(&self) -> &str {
21.         &self.tag_name
22.     }
23. 
24.     /// Returns assets attached to the release.
25.     #[must_use]
26.     pub fn assets(&self) -> &[ReleaseAsset] {
27.         &self.assets
28.     }
29. }
30. 
31. /// A downloadable GitHub release asset.
32. #[derive(Debug, Deserialize)]
33. pub struct ReleaseAsset {
34.     name: String,
35. }
36. 
37. impl ReleaseAsset {
38.     /// Returns the asset name.
39.     #[must_use]
40.     pub fn name(&self) -> &str {
41.         &self.name
42.     }
43. }
44. 
45. /// Errors returned by the GitHub release client.
46. #[derive(Debug, Error)]
47. pub enum ReleaseClientError {
48.     /// The HTTP request or response decoding failed.
49.     #[error(transparent)]
50.     Http(#[from] reqwest::Error),
51.     /// GitHub returned no releases for Derrick.
52.     #[error("GitHub returned no releases for lgulliver/derrick")]
53.     NoRelease,
54. }
55. 
56. /// Reqwest-backed client for GitHub release metadata.
57. #[derive(Debug, Clone)]
58. pub struct ReqwestReleaseClient {
59.     client: reqwest::Client,
60.     releases_url: &'static str,
61. }
62. 
63. impl Default for ReqwestReleaseClient {
64.     fn default() -> Self {
65.         Self {
66.             client: reqwest::Client::new(),
67.             releases_url: RELEASES_URL,
68.         }
69.     }
70. }
71. 
72. impl ReqwestReleaseClient {
73.     /// Creates a release client using the default GitHub endpoint.
74.     #[must_use]
75.     pub fn new() -> Self {
76.         Self::default()
77.     }
78. 
79.     /// Fetches the latest Derrick release from GitHub.
80.     ///
81.     /// This method performs network I/O against GitHub's releases API.
82.     pub async fn latest_release(&self) -> Result<Release, ReleaseClientError> {
83.         let mut releases: Vec<Release> = self
84.             .client
85.             .get(self.releases_url)
86.             .header(USER_AGENT, concat!("derrick/", env!("CARGO_PKG_VERSION")))
87.             .header(ACCEPT, "application/vnd.github+json")
88.             .send()
89.             .await?
90.             .error_for_status()?
91.             .json()
92.             .await?;
93. 
94.         releases.pop().ok_or(ReleaseClientError::NoRelease)
95.     }
96. }
97. 
98. fn deserialize_semver_tag_name<'de, D>(deserializer: D) -> Result<String, D::Error>
99. where
100.     D: Deserializer<'de>,
101. {
102.     let tag_name = String::deserialize(deserializer)?;
103.     Ok(semver_tag_name(&tag_name))
104. }
105. 
106. fn semver_tag_name(tag_name: &str) -> String {
107.     let trimmed = tag_name.trim();
108.     if let Some(version) = trimmed.strip_prefix('v') {
109.         version.to_owned()
110.     } else if let Some(nightly) = trimmed.strip_prefix("nightly-") {
111.         format!("0.0.0-nightly.{nightly}")
112.     } else {
113.         trimmed.to_owned()
114.     }
115. }
116. 
117. #[cfg(test)]
118. mod tests {
119.     use super::{semver_tag_name, Release};
120. 
121.     type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;
122. 
123.     #[test]
124.     fn release_deserializes_tag_and_asset_names() -> TestResult {
125.         let release: Release = serde_json::from_str(
126.             r#"{
127.                 "tag_name": "v1.2.3",
128.                 "assets": [
129.                     { "name": "derrick-aarch64-apple-darwin.tar.gz" }
130.                 ]
131.             }"#,
132.         )?;
133. 
134.         assert_eq!(release.tag_name(), "1.2.3");
135.         match release.assets() {
136.             [asset] => assert_eq!(asset.name(), "derrick-aarch64-apple-darwin.tar.gz"),
137.             assets => assert_eq!(assets.len(), 1),
138.         }
139.         Ok(())
140.     }
141. 
142.     #[test]
143.     fn nightly_release_tags_are_normalized_to_semver_prereleases() {
144.         assert_eq!(
145.             semver_tag_name("nightly-20260524"),
146.             "0.0.0-nightly.20260524"
147.         );
148.         assert_eq!(
149.             semver_tag_name("nightly-20260518.1"),
150.             "0.0.0-nightly.20260518.1"
151.         );
152.     }
153. }
154.

